def pluck(arr):
    if not arr:
        return []

    min_even = None
    min_index = None

    for i, value in enumerate(arr):
        if value % 2 == 0:
            if min_even is None or value < min_even:
                min_even = value
                min_index = i

    if min_even is None:
        return []

    return [min_even, min_index]
