def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == 0:
        return x == 1 or x == 0  # 0^0 is sometimes defined as 1, but typically we consider 0^int=0 for int>0
    # We need to find if there exists an integer k such that n**k == x
    # Since n**int = x, and we're looking for integer exponent
    # We can try taking log, but floating point issues might occur
    # Better approach: iterate through possible exponents

    if x == 1:
        return True  # n^0 = 1 for any n != 0

    if x == 0:
        return n == 0  # 0^k = 0 for k > 0, but we need to handle carefully

    # For positive x and n > 1, we can check by repeated multiplication
    # Or use logarithms with tolerance

    if n < 0:
        # Handle negative base
        # n**k = x. If k is even, result is positive. If k is odd, result is negative.
        if x > 0:
            # Check if x is a power of |n| with even exponent
            import math
            if x == 1:
                return True
            # We need n**k = x where k is integer
            # Try small exponents
            for k in range(0, 100):
                if n**k == x:
                    return True
                if abs(n**k) > abs(x):
                    break
            return False
        else:
            # x is negative, need odd exponent

