def is_simple_power(x, n):
    if n == 0:
        return x == 1
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    if x == 1:
        return True
    if x == 0:
        return False
    if n > 0 and x > 0:
        import math
        if n == 1:
            return x == 1
        log_x = math.log(x)
        log_n = math.n
        if log_n == 0:
            return x == 1
        exponent = log_x / log_n
        rounded_exponent = round(exponent)
        if abs(exponent - rounded_exponent) < 1e-10:
            return n ** int(rounded_exponent) == x
        return False
    elif n < 0 and x > 0:
        import math
        log_x = math.log(x)
        log_n = math.log(abs(n))
        if log_n == 0:
            return x == 1
        exponent = log_x / log_n
        rounded_exponent = round(exponent)
        if abs(exponent - rounded_exponent) < 1e-10:
            return n ** int(rounded_exponent) == x
        return False
    else:
        return False
</code>

