    result = []
    for char in s:
        if char.isalpha():
            # Determine the base ASCII value for lowercase or uppercase letters
            base = ord('a') if char.islower() else ord('A')
            # Shift the character by 4 (2 * 2)
            shifted = (ord(char) - base + 4) % 26 + base
